import { useMutation, UseMutationOptions } from '@tanstack/react-query';
import { CreateWalletResponseDTO, CreateWalletRequestDTO } from '~/entities/wallet/api/dtos/create-wallet';
import { walletApi } from '~/entities/wallet/api/wallet-api';
import { CBDCAxiosError } from '~/shared/@types/error';

export const useCreateWalletMutation = (
  options?: UseMutationOptions<CreateWalletResponseDTO, CBDCAxiosError, CreateWalletRequestDTO>,
) => {
  const mutation = useMutation<CreateWalletResponseDTO, CBDCAxiosError, CreateWalletRequestDTO>({
    ...options,
    mutationFn: walletApi.createWallet,
  });

  return {
    ...mutation,
  };
};
